"use client"

import type * as React from "react"
import { UploadIcon } from "lucide-react"
import { FileTrigger as FileTriggerPrimitive, type FileTriggerProps } from "react-aria-components"

import { Button } from "@/components/ui/button"

/**
 * React Aria FileTrigger wrapped around the aria-nova Button. Members map to
 * FileTrigger props: multiple = allowsMultiple, accept = acceptedFileTypes,
 * directory = acceptDirectory.
 */
function FileTrigger({
  children,
  variant = "outline",
  size = "default",
  className,
  isDisabled,
  ...props
}: Omit<FileTriggerProps, "children"> & {
  children?: React.ReactNode
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  isDisabled?: boolean
}) {
  return (
    <FileTriggerPrimitive {...props}>
      <Button data-slot="file-trigger" variant={variant} size={size} className={className} isDisabled={isDisabled}>
        <UploadIcon data-icon="inline-start" />
        {children ?? (props.allowsMultiple ? "Choose files" : props.acceptDirectory ? "Choose folder" : "Choose file")}
      </Button>
    </FileTriggerPrimitive>
  )
}

export { FileTrigger }
